def solve(shape, W=7, H=7):
    cells = [(i,j) for i in range(H) for j in range(W) if shape[i][j]]
    cellset = set(cells)
    # pieces: 2x2 squares and L trominoes fully inside
    pieces = []
    for i in range(H-1):
        for j in range(W-1):
            sq = [(i,j),(i,j+1),(i+1,j),(i+1,j+1)]
            if all(c in cellset for c in sq):
                pieces.append(('sq', frozenset(sq)))
    for i in range(H-1):
        for j in range(W-1):
            box = [(i,j),(i,j+1),(i+1,j),(i+1,j+1)]
            for miss in range(4):
                tri = [c for k,c in enumerate(box) if k != miss]
                if all(c in cellset for c in tri) and tri not in [p[1] for p in []]:
                    pieces.append(('L', miss, frozenset(tri)))
    # exact cover
    res = []
    def bt(remaining, chosen):
        if not remaining:
            res.append(list(chosen)); return
        c = min(remaining)
        for p in pieces:
            if c in p[-1] and p[-1] <= remaining:
                bt(remaining - p[-1], chosen + [p])
    bt(frozenset(cells), [])
    return res

